import { assertEquals, assertThrows } from "jsr:@std/assert@1.0.19";
import {
  contents,
  type Extension,
  renderTable,
  replaceBetweenMarkers,
  summary,
} from "./readme-extensions.ts";

const START =
  "<!-- EXTENSIONS_START: generated by scripts/readme-extensions.ts, do not edit -->";
const END = "<!-- EXTENSIONS_END -->";

const ext = (registry: Extension["registry"]): Extension => ({
  dir: "webshot",
  manifest: {
    name: "@taylor/webshot",
    version: "2026.10.11.1",
    description: "Full-page screenshots (PNG | JPEG). Runs headless\nChrome.",
    models: ["webshot.ts"],
  },
  registry,
});

Deno.test("summary keeps the first sentence on one line and escapes pipes", () => {
  assertEquals(summary("One thing. Another."), "One thing.");
  assertEquals(summary("No period\nhere"), "No period here");
  assertEquals(summary("a | b."), "a \\| b.");
  assertEquals(summary(undefined), "");
});

Deno.test("contents counts each kind with plurals", () => {
  assertEquals(
    contents({ name: "x", version: "1", models: ["a.ts"] }),
    "1 behavior",
  );
  assertEquals(
    contents({ name: "x", version: "1", models: ["a", "b"], workflows: ["w"] }),
    "2 behaviors, 1 workflow",
  );
  assertEquals(
    contents({ name: "x", version: "1", behaviors: ["a"], models: ["b"] }),
    "2 behaviors",
  );
});

Deno.test("renderTable shows registry status", () => {
  assertEquals(
    renderTable([ext(null)]).split("\n")[2],
    "| [@taylor/webshot](webshot/) | Full-page screenshots (PNG \\| JPEG). | 1 behavior | `2026.10.11.1` | not published yet |",
  );
  const published = renderTable([
    ext({
      latestVersion: "2026.10.11.1",
      deprecated: false,
      supersededBy: null,
    }),
  ]);
  assertEquals(
    published.endsWith(
      "[`2026.10.11.1`](https://swamp-club.com/extensions/@taylor/webshot) |",
    ),
    true,
  );
  const deprecated = renderTable([
    ext({
      latestVersion: "1",
      deprecated: true,
      supersededBy: "@taylor/shot2",
    }),
  ]);
  assertEquals(deprecated.includes("deprecated, use `@taylor/shot2`"), true);
  assertEquals(renderTable([]), "_No extensions yet._");
});

Deno.test("replaceBetweenMarkers only touches the generated section", () => {
  const readme = `# Title\n\n${START}\nold table\n${END}\n\nFooter\n`;
  assertEquals(
    replaceBetweenMarkers(readme, "new table"),
    `# Title\n\n${START}\nnew table\n${END}\n\nFooter\n`,
  );
  assertThrows(
    () => replaceBetweenMarkers("# no markers", "x"),
    Error,
    "must contain the markers",
  );
});
